const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  try {
    // 1. Geometry & Time Definitions
    const eastern_point = ee.Geometry.Point([-137.527803, 48.504441]);
    const western_point = ee.Geometry.Point([-169.318365, 46.750838]);

    const anomaly_start_date = '2016-01-01';
    const anomaly_end_date = '2016-01-31';

    const baseline_start_year = 2003;
    const baseline_end_year = 2012;
    const target_month = 1; // January

    const scale = 1000; // Appropriate for OISST V2 (0.25 degree resolution) and point geometries.

    // 2. Data Acquisition
    const oisst_collection = ee.ImageCollection('NOAA/OISST/V2/DAILY');

    // Filter for baseline period (January of each year from 2003-2012)
    let baseline_images = ee.ImageCollection([]);
    for (let year = baseline_start_year; year <= baseline_end_year; year++) {
      const start_date = ee.Date.fromYMD(year, target_month, 1);
      const end_date = start_date.advance(1, 'month');
      const monthly_images = oisst_collection
        .filterDate(start_date, end_date)
        .select('sst');
      if (await monthly_images.size().getInfo() > 0) {
        baseline_images = baseline_images.merge(monthly_images.mean());
      }
    }

    // Check if baseline collection is empty
    const baseline_size = await baseline_images.size().getInfo();
    if (baseline_size === 0) {
      console.log("C1: No data found for the baseline period (January 2003-2012).");
      return;
    }

    // Calculate baseline mean SST for both locations
    const baseline_eastern_mean = await baseline_images.mean().reduceRegion({
      reducer: ee.Reducer.mean(),
      geometry: eastern_point,
      scale: scale,
      maxPixels: 1e9
    }).get('sst').getInfo();

    const baseline_western_mean = await baseline_images.mean().reduceRegion({
      reducer: ee.Reducer.mean(),
      geometry: western_point,
      scale: scale,
      maxPixels: 1e9
    }).get('sst').getInfo();

    if (baseline_eastern_mean === null || baseline_western_mean === null) {
      console.log("C3: Baseline calculation failed (null result for SST).");
      return;
    }
    console.log(`Baseline (2003-2012) Eastern SST: ${baseline_eastern_mean.toFixed(2)} °C`);
    console.log(`Baseline (2003-2012) Western SST: ${baseline_western_mean.toFixed(2)} °C`);

    // Filter for anomaly period (January 2016)
    const anomaly_period_images = oisst_collection
      .filterDate(anomaly_start_date, anomaly_end_date)
      .select('sst');

    const anomaly_size = await anomaly_period_images.size().getInfo();
    if (anomaly_size === 0) {
      console.log("C1: No data found for the anomaly period (January 2016).");
      return;
    }
    const current_eastern_mean = await anomaly_period_images.mean().reduceRegion({
      reducer: ee.Reducer.mean(),
      geometry: eastern_point,
      scale: scale,
      maxPixels: 1e9
    }).get('sst').getInfo();

    const current_western_mean = await anomaly_period_images.mean().reduceRegion({
      reducer: ee.Reducer.mean(),
      geometry: western_point,
      scale: scale,
      maxPixels: 1e9
    }).get('sst').getInfo();

    if (current_eastern_mean === null || current_western_mean === null) {
      console.log("C3: Current period calculation failed (null result for SST).");
      return;
    }
    console.log(`Current (2016) Eastern SST: ${current_eastern_mean.toFixed(2)} °C`);
    console.log(`Current (2016) Western SST: ${current_western_mean.toFixed(2)} °C`);

    // 4. Anomaly Calculation
    const eastern_anomaly = current_eastern_mean - baseline_eastern_mean;
    const western_anomaly = current_western_mean - baseline_western_mean;

    if (isNaN(eastern_anomaly) || isNaN(western_anomaly)) {
      console.log("C3: Anomaly calculation resulted in NaN.");
      return;
    }

    // 5. Validation & Final Answer
    console.log(`Eastern Anomaly: ${eastern_anomaly.toFixed(2)} °C`);
    console.log(`Western Anomaly: ${western_anomaly.toFixed(2)} °C`);

    if (eastern_anomaly > western_anomaly) {
      console.log("A");
    } else {
      console.log("B");
    }
  } catch (error) {
    console.error("D: An Earth Engine error occurred:", error);
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
